UPDATE corpus SET
  trends = '[{"title": "Brent has risen for three consecutive weeks, and the recovery horizon moved out a year", "detail": "The published Pulse shows Brent USD 89.31 to USD 96.28 (+7.80% wow) to USD 104.35 (+8.38% wow). The change in the 11 Sept edition is not the level but the horizon: the IEA now expects normal Middle East flows only in 2027, against a previous 2026 assumption. Malakoff''s fuel exposure therefore stops being a spike to absorb and becomes a cost base to plan against, and the 11 Sept Pulse adds Gas Malaysia''s reference-price pass-through lag as a separate named channel, which the 4 Sept Pulse did not isolate.", "entities": ["malakoff", "gas_malaysia"], "indicator": "brent"}, {"title": "Bank Muamalat''s funding pressure widened from one channel to four", "detail": "On 4 Sept the read was a stable funding backdrop with a narrowing lending spread of 2.36% and deposit growth slowing to 5.6%. By 11 Sept four channels are live at once: the 10-year MGS yield rose 16 basis points to 4.14%, the ECB lifted its deposit rate to 2.50% with more signalled, net foreign outflow widened to RM 640.3 mn, and research houses expect higher second-half credit costs. The FOMC on 15-16 Sept and the ECB increase taking effect on 16 Sept land in the same week.", "entities": ["bank_muamalat"], "indicator": "mgs10"}, {"title": "Fleet fuel costs reversed from a tailwind to a headwind in one week", "detail": "The 4 Sept Pulse graded unsubsidised fuel Positive on a 5 sen cut, naming Pos Malaysia, Kontena Nasional and Tradewinds Plantation. The 11 Sept Pulse grades the same row Negative on a 25 sen increase, with Peninsular diesel moving RM 4.67 to RM 4.92. This is the only Pulse row to flip grade between the two editions. BUDI95 held at RM 1.99 throughout, so the exposure is fleet and haulage, not consumer.", "entities": ["pos_malaysia", "kontena", "tradewinds"], "indicator": "diesel"}, {"title": "MMC Ports'' demand signals strengthened while no throughput gain was confirmed", "detail": "Across both editions the demand evidence accumulated: China''s Aug exports rose 25.0%, Malaysia''s Jan-Jul trade rose 24.7% to RM 2.16 tn with exports up 29.2%, manufacturing sales reached RM 177.3 bn, and typhoon disruption at Chinese ports delayed 4.3 mn TEU with Westports cutting yard density to 80%. Both editions are careful that none of this is booked volume. Against that, the 4 Sept edition carries the Penang ferry collision as a liability and safety-directive exposure.", "entities": ["ptp", "johor_port", "northport", "penang_port"], "indicator": null}, {"title": "Malakoff''s story shifted from cost victim to capacity beneficiary", "detail": "The 4 Sept edition frames Malakoff almost entirely through fuel cost and valuation multiples. The 11 Sept edition adds three forward-looking references: a 9 GW gas-fired capacity requirement by 2032 with no new capacity due in 2026-2027, BIMB Research projecting 10.6% sector core earnings growth with higher Tanjung Bin availability and a possible dividend resumption, and Wood Mackenzie''s regional LNG demand lead. The cost pressure is unchanged; what is new is that scarce dependable capacity is now an asset.", "entities": ["malakoff", "gas_malaysia"], "indicator": null}, {"title": "The data-centre theme moved from demand projection into execution, without a Group award", "detail": "The 4 Sept edition notes Singapore awarding only 200 MW, supporting the case for Johor demand. By 11 Sept the theme is concrete: data centres reached 9.3% of Malaysian electricity use against a 7% average, Firmus signed a multi-year OpenAI agreement for two Malaysian sites, and Pekat and TRC secured RM 207.16 mn of data-centre works. Every item is explicit that no AlBukhary company holds an award, so the read stays a tenant-quality and tender-margin reference for TBIP, SAC and MMC Engineering.", "entities": ["tbip", "sac", "mmc_eng", "gas_malaysia"], "indicator": null}, {"title": "Proton''s momentum is intact but the competitive and cost backdrop changed", "detail": "On 4 Sept Proton posted record monthly domestic sales of 22,632 units, 27.9% Aug share, 40.2% year-to-date growth and its best exports since 2011. By 11 Sept the read is more contingent: sub-RM 60,000 S70 variants broaden the range specifically because higher fuel costs test demand, motor-vehicle sales growth of 7.9% feeds the order book, and BYD dropped its Tanjung Malim plant while advancing local assembly talks, keeping contract-manufacturing competition active.", "entities": ["proton", "drb_hicom"], "indicator": null}, {"title": "Aviation''s fuel hedge held while jet-fuel costs kept climbing", "detail": "Malaysia Aviation Group (MAG) maintained its fuel hedging programme as jet-fuel costs rose alongside Brent''s three-week climb, insulating near-term costs, while AirAsia moved to raise up to USD 1 bn and RM 700 mn for refinancing. The sector is managing the same cost pressure hitting Malakoff and Gas Malaysia (Trend 1) through hedging and balance-sheet action rather than price relief.", "entities": ["pos_aviation", "sac"], "indicator": null}, {"title": "Property transactions topped RM105bn but the read for Group holdings stayed mixed", "detail": "Malaysia recorded RM 105.12 bn of property transactions in 1H2026, a market-wide increase that sits alongside Glenmarie Properties and MMC Land without a clear signal yet on which benefits most. The data-centre-driven demand already flagged for TBIP and SAC (Trend 6) remains the more concrete growth channel; broader residential and commercial transaction volume is a market backdrop rather than a confirmed Group tailwind.", "entities": ["glenmarie", "mmc_land"], "indicator": null}, {"title": "Malaysian banks'' rising credit-cost backdrop frames Bank Muamalat''s funding squeeze", "detail": "Maybank''s RM 4.83 bn completion of its Ageas stake acquisition and USD 700 mn two-part bond sale show larger banks locking in capital and dollar funding ahead of the same higher second-half credit costs research houses now expect sector-wide. This is the competitive and cost context behind Bank Muamalat''s funding pressure widening from one channel to four (Trend 2).", "entities": ["bank_muamalat"], "indicator": null}]',
  indicators = '[{"id": "brent", "label": "Brent Crude", "unit": "USD/bbl", "direction_bad": "up", "series": [{"date": "2026-08-28", "value": 89.31}, {"date": "2026-09-04", "value": 96.28}, {"date": "2026-09-11", "value": 104.35}, {"date": "2026-09-18", "value": 104.87}], "note": "Published Pulse values. 4 Sept +7.80% wow; 11 Sept +8.38% wow; 18 Sept +0.25% wow, holding above USD100 for a second week. Strait of Hormuz traffic impaired."}, {"id": "usdmyr", "label": "USD/MYR", "unit": "", "direction_bad": "up", "series": [{"date": "2026-08-28", "value": 4.0275}, {"date": "2026-09-04", "value": 4.0455}, {"date": "2026-09-11", "value": 4.0685}, {"date": "2026-09-18", "value": 4.0808}], "note": "Ringgit weaker as the value rises. Feeds DRB-HICOM imported-component costs. 18 Sept +0.30% wow as the Fed hike kept pressure on the ringgit."}, {"id": "cnymyr", "label": "CNY/MYR", "unit": "", "direction_bad": "up", "series": [{"date": "2026-08-28", "value": 0.5992}, {"date": "2026-09-04", "value": 0.6028}, {"date": "2026-09-11", "value": 0.6064}, {"date": "2026-09-18", "value": 0.6092}], "note": "Yuan-denominated machinery and component costs for DRB-HICOM and data-centre projects. 18 Sept +0.46% wow, a faster move than against the dollar."}, {"id": "mgs10", "label": "10-Year MGS Yield", "unit": "%", "direction_bad": "up", "series": [{"date": "2026-09-04", "value": 3.98}, {"date": "2026-09-11", "value": 4.14}, {"date": "2026-09-18", "value": 3.92}], "note": "Up 16 basis points to 11 Sept. Raises Bank Muamalat funding costs and pressures sukuk and treasury valuations. 18 Sept fell 26 basis points to 3.92%; realised benefit for Bank Muamalat depends on its funding mix."}, {"id": "diesel", "label": "Peninsular diesel (unsubsidised)", "unit": "RM/litre", "direction_bad": "up", "series": [{"date": "2026-08-27", "value": 4.72}, {"date": "2026-09-03", "value": 4.67}, {"date": "2026-09-10", "value": 4.92}, {"date": "2026-09-17", "value": 5.27}], "note": "Fell 5 sen, then rose 25 sen for the 10-16 Sept window, then rose a further 35 sen to RM 5.27 on 17 Sept — up 60 sen/litre in two weeks. BUDI95 subsidised RON95 stays at RM 1.99/litre within the 300-litre monthly cap. Hits unsubsidised fleet volumes at Pos Malaysia, Kontena Nasional and Tradewinds Plantation until surcharges catch up."}, {"id": "klci", "label": "FBM KLCI", "unit": "pts", "direction_bad": "down", "series": [{"date": "2026-08-28", "value": 1725.88}, {"date": "2026-09-04", "value": 1708.1}, {"date": "2026-09-11", "value": 1686.74}, {"date": "2026-09-18", "value": 1665.56}], "note": "Gave up the 1,700 level, then fell a further 1.26% wow to 1,665.56 on 18 Sept. No AlBukhary business marks to the index."}, {"id": "foreign_flow", "label": "Net Foreign Flow (weekly outflow)", "unit": "RM mn", "direction_bad": "up", "series": [{"date": "2026-08-21", "value": 549.1}, {"date": "2026-08-28", "value": 366.0}, {"date": "2026-09-04", "value": 640.3}, {"date": "2026-09-11", "value": 160.3}], "note": "Outflow narrowed then widened to RM 640.3 mn, then narrowed sharply to RM 160.3 mn for the week ended 11 Sept — a sixth straight week of foreign selling but at a quarter of the prior pace; local institutions also sold."}, {"id": "palm_stocks", "label": "Palm oil closing stocks", "unit": "mn tonnes", "direction_bad": "up", "series": [{"date": "2026-07-31", "value": 2.62}, {"date": "2026-08-31", "value": 2.82}], "note": "Up 7.48%. Output reached 1.81 mn tonnes; exports fell to 1.29 mn tonnes."}]'
